{
  "a_sentences": [
    {
      "a_text": "Selon l'art. 264 al. 1 CO, la personne assurée qui restitue la chose louée avant l'échéance n'est libérée de ses obligations envers l'assureur que si elle lui propose un nouveau locataire acceptable, solvable et prêt à reprendre le bail aux mêmes conditions.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Si elle ne le fait pas, elle doit payer le loyer jusqu'à l'échéance du bail ou jusqu'à la date à laquelle celui-ci peut être résilié selon le contrat ou la loi.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Il incombe en principe à la personne assurée qui quitte le logement avant terme de rechercher un locataire de remplacement.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Il faut examiner au cas par cas si l'assureur a violé son devoir de réduire le dommage.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "En l'espèce, la durée restante du bail était de près de sept mois, ce qui ne constitue pas une longue période.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Il appartient à la personne assurée qui restitue la chose avant l'échéance de proposer un locataire de remplacement solvable, objectivement acceptable et prêt à reprendre le bail aux mêmes conditions.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale a considéré à juste titre que l'absence de recherches de l'assureur était une omission moins grave que le refus explicite de la personne assurée de proposer un locataire de remplacement.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette le recours, dans la mesure de sa recevabilité.",
      "b_propositions": ["P8"]
    }
  ]
}
